// Cosmos clips (dashboard/cosmos/clips.mjs): the pure half — sniff, name rules, the provenance record, the manifest on disk.
//   node --test dashboard/cosmos/clips.test.mjs
// Placeholder hosts only (alpha-site.test); images are generated by testimages.mjs or are hand-built byte headers.
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {
  SNIFF_BYTES, MAX_CLIP_BYTES, MAX_CLIPS, MANIFEST_FILE, TMP_DIR, TMP_MAX_AGE_MS,
  sniff, extFamily, reducePageUrl, cleanTitle, clipRecord, normaliseManifest, capClips, pendingWork, readManifest, writeManifest,
} from './clips.mjs';
import { clipTags, inferTypeFromClip } from './infer.mjs';
import { solidPng } from './testimages.mjs';

const AT = '2026-11-11T10:00:00.000Z';
const tmp = () => fs.mkdtempSync(path.join(os.tmpdir(), 'cosmos-clips-'));
const file = (n, ext = 'png') => `clip-${String(n).padStart(12, '0').replace(/[^0-9a-f]/g, 'a')}.${ext}`;
const entry = (n, over = {}) => ({ file: file(n), host: 'alpha-site.test', pageHost: '', page: '', title: 'Grab from alpha-site.test', tags: ['clipped'], type: 'misc', at: AT, applied: false, ...over });
const ascii = (s) => [...s].map((c) => c.charCodeAt(0));

describe('constants', () => {
  it('say what the spec says', () => {
    assert.equal(SNIFF_BYTES, 16);
    assert.equal(MAX_CLIP_BYTES, 64 * 1024 * 1024);
    assert.equal(MAX_CLIPS, 5000);
    assert.equal(MANIFEST_FILE, 'clips.json');
    assert.equal(TMP_DIR, '.grab-tmp');
    assert.equal(TMP_MAX_AGE_MS, 3600e3);
  });
});

describe('sniff', () => {
  const mp4 = (brand) => Uint8Array.from([0, 0, 0, 0x18, ...ascii('ftyp'), ...ascii(brand), 0, 0, 0, 0]);
  const rows = [
    ['a generated PNG', solidPng(10, 20, 30, 4, 4), { family: 'png', ext: '.png', kind: 'image' }],
    ['JPEG', Uint8Array.from([0xff, 0xd8, 0xff, 0xe0, 0, 0x10, ...ascii('JFIF')]), { family: 'jpeg', ext: '.jpg', kind: 'image' }],
    ['GIF87a', Uint8Array.from([...ascii('GIF87a'), 1, 0, 1, 0]), { family: 'gif', ext: '.gif', kind: 'image' }],
    ['GIF89a', Uint8Array.from([...ascii('GIF89a'), 1, 0, 1, 0]), { family: 'gif', ext: '.gif', kind: 'image' }],
    ['WEBP', Uint8Array.from([...ascii('RIFF'), 10, 0, 0, 0, ...ascii('WEBP'), ...ascii('VP8 ')]), { family: 'webp', ext: '.webp', kind: 'image' }],
    ['MP4 (isom)', mp4('isom'), { family: 'isobmff', ext: '.mp4', kind: 'video', mime: 'video/mp4' }],
    ['MOV (qt brand)', mp4('qt  '), { family: 'isobmff', ext: '.mov', kind: 'video', mime: 'video/quicktime' }],
    ['WEBM', Uint8Array.from([0x1a, 0x45, 0xdf, 0xa3, 0x9f, 0x42, 0x86, 0x81]), { family: 'webm', ext: '.webm', kind: 'video' }],
  ];
  for (const [name, bytes, want] of rows) {
    it(name, () => {
      const got = sniff(bytes.subarray(0, 16));
      for (const [k, v] of Object.entries(want)) assert.equal(got[k], v, k);
    });
  }
  const refused = [
    ['SVG', Buffer.from('<svg xmlns="http://www.w3.org/2000/svg"/>')],
    ['HTML', Buffer.from('<!doctype html><html>')],
    ['a script', Buffer.from('#!/bin/sh\nrm -rf x\n')],
    ['a Windows executable', Buffer.from('MZ\x90\x00\x03\x00\x00\x00\x04\x00\x00\x00')],
    ['RIFF that is not WEBP (a WAV)', Uint8Array.from([...ascii('RIFF'), 1, 0, 0, 0, ...ascii('WAVE')])],
    ['too short for PNG', Uint8Array.from([0x89, 0x50, 0x4e, 0x47])],
    ['too short for ftyp', Uint8Array.from([0, 0, 0, 0x18, ...ascii('ftyp')])],
    ['empty', new Uint8Array(0)],
  ];
  for (const [name, bytes] of refused) it('refuses ' + name, () => assert.equal(sniff(bytes), null));
  it('refuses a non-array', () => { assert.equal(sniff(null), null); assert.equal(sniff(undefined), null); assert.equal(sniff({}), null); });
});

describe('extFamily', () => {
  it('maps the extensions a clip may have, any case, and nothing else', () => {
    const fam = { '.png': 'png', '.PNG': 'png', '.jpg': 'jpeg', '.jpeg': 'jpeg', '.gif': 'gif', '.webp': 'webp', '.mp4': 'isobmff', '.m4v': 'isobmff', '.mov': 'isobmff', '.MOV': 'isobmff', '.webm': 'webm' };
    for (const [e, f] of Object.entries(fam)) assert.equal(extFamily(e), f, e);
    for (const e of ['.svg', '.html', '.avif', '.bmp', '.exe', '', '.', 'png', '.toString', '.__proto__', null, 5]) assert.equal(extFamily(e), null, String(e));
  });
});

describe('reducePageUrl and cleanTitle', () => {
  it('keeps host and path only: no scheme detail, query, hash, port or credentials', () => {
    assert.deepEqual(reducePageUrl('https://user:pw@Alpha-Site.test:8080/a/b?token=1#frag'), { host: 'alpha-site.test', hostPath: 'alpha-site.test/a/b' });
    assert.deepEqual(reducePageUrl('http://alpha-site.test/'), { host: 'alpha-site.test', hostPath: 'alpha-site.test' });
    const long = reducePageUrl('https://alpha-site.test/' + 'x'.repeat(500));
    assert.ok(long.hostPath.length <= 'alpha-site.test'.length + 200);
  });
  it('refuses anything that is not a web page', () => {
    for (const u of ['', null, undefined, 5, 'not a url', 'file:///C:/x.png', 'javascript:alert(1)', 'data:text/html,hi', 'ftp://alpha-site.test/x', 'https://' + 'a'.repeat(5000)]) assert.equal(reducePageUrl(u), null, String(u).slice(0, 30));
  });
  it('the result carries no query or hash', () => {
    const r = reducePageUrl('https://alpha-site.test/p?secret=abc#me');
    assert.ok(!JSON.stringify(r).includes('secret') && !JSON.stringify(r).includes('#'));
  });
  it('cleanTitle: one clean line of at most 200 characters', () => {
    assert.equal(cleanTitle('  Acme\n\tposter\u0000  launch '), 'Acme poster launch');
    assert.equal(cleanTitle('x'.repeat(500)).length, 200);
    assert.equal(cleanTitle(null), '');
    assert.equal(cleanTitle('\n\n'), '');
  });
});

describe('clipRecord', () => {
  it('a placeholder acme poster: tags and type are what infer.mjs says, the query and hash are gone, the source host is a tag', () => {
    const r = clipRecord({ file: file(1), host: 'alpha-site.test', pageUrl: 'https://www.alpha-site.test/blog/acme-poster-launch?utm=1#x', pageTitle: 'Acme poster launch day', leaf: 'poster-300.png', mime: 'image/png', at: AT });
    assert.deepEqual(r.tags, clipTags({ pageUrl: 'https://www.alpha-site.test/blog/acme-poster-launch', pageTitle: 'Acme poster launch day', siteName: 'alpha-site.test' }));
    assert.deepEqual(r.tags, ['clipped', 'alpha-site.test', 'acme', 'poster', 'launch']);
    assert.equal(r.type, inferTypeFromClip({ mediaUrl: 'https://alpha-site.test/poster-300.png', pageUrl: 'https://www.alpha-site.test/blog/acme-poster-launch', pageTitle: 'Acme poster launch day', mime: 'image/png' }));
    assert.equal(r.page, 'www.alpha-site.test/blog/acme-poster-launch');
    assert.equal(r.pageHost, 'www.alpha-site.test');
    assert.ok(!JSON.stringify(r).includes('utm') && !JSON.stringify(r).includes('#x'));
    assert.deepEqual([r.title, r.applied, r.at, r.file, r.host], ['Acme poster launch day', false, AT, file(1), 'alpha-site.test']);
  });
  it('no page: the title falls back to "Grab from <host>", the tags are the marker and the source host, a video is motion', () => {
    const r = clipRecord({ file: file(2, 'mp4'), host: 'alpha-site.test', pageUrl: '', pageTitle: '', leaf: 'a.mp4', mime: 'video/mp4', at: AT });
    assert.equal(r.title, 'Grab from alpha-site.test');
    assert.deepEqual(r.tags, ['clipped', 'alpha-site.test']);
    assert.equal(r.type, 'motion');
    assert.deepEqual([r.pageHost, r.page], ['', '']);
  });
  it('a page on another host adds both hosts as tags', () => {
    const r = clipRecord({ file: file(3), host: 'cdn.beta.test', pageUrl: 'https://alpha-site.test/x', pageTitle: '', leaf: 'a.png', mime: 'image/png', at: AT });
    assert.deepEqual(r.tags.slice(0, 3), ['clipped', 'alpha-site.test', 'cdn.beta.test']);
  });
});

describe('normaliseManifest, capClips, pendingWork', () => {
  it('keeps good rows, drops bad ones, collapses repeats to the first', () => {
    const m = normaliseManifest({
      v: 1,
      clips: [
        entry(1), entry(1, { title: 'again' }), { file: '../evil.png', host: 'alpha-site.test' }, { file: file(2), host: 'Not A Host!' },
        entry(3, { type: 'nonsense', tags: ['  Spaced  Tag ', 7, 'a'.repeat(50), 'clipped', 'clipped'] }), null, 'x', { file: 'clip-1.png' },
        { ...entry(4), file: 'clip-bbbbbbbbbbbb.svg' },
      ],
    });
    assert.deepEqual(m.clips.map((c) => c.file), [file(1), file(3)]);
    assert.equal(m.clips[0].title, 'Grab from alpha-site.test');
    assert.equal(m.clips[1].type, 'misc');
    assert.deepEqual(m.clips[1].tags, ['spaced tag', 'clipped']);
  });
  it('is null for anything that is not a v1 manifest', () => {
    for (const x of [null, [], 'x', 5, {}, { v: 2, clips: [] }, { v: 1 }, { v: 1, clips: {} }]) assert.equal(normaliseManifest(x), null, JSON.stringify(x));
  });
  it('the cap drops the oldest applied entries first, then the oldest', () => {
    const list = [entry(1, { applied: true }), entry(2), entry(3, { applied: true }), entry(4), entry(5)];
    assert.deepEqual(capClips(list, 4).map((c) => c.file), [file(2), file(3), file(4), file(5)]);
    assert.deepEqual(capClips(list, 3).map((c) => c.file), [file(2), file(4), file(5)]);
    assert.deepEqual(capClips(list, 2).map((c) => c.file), [file(4), file(5)]);
    assert.equal(capClips(list, 10), list);
  });
  it('a manifest bigger than the cap is cut to 5000', () => {
    const clips = Array.from({ length: MAX_CLIPS + 7 }, (_, i) => entry(i.toString(16)));
    const out = normaliseManifest({ v: 1, clips });
    assert.equal(out.clips.length, MAX_CLIPS);
    assert.equal(out.clips[MAX_CLIPS - 1].file, clips[MAX_CLIPS + 6].file);
  });
  it('pendingWork pairs waiting entries with the work an index run made, and leaves the rest', () => {
    const clips = [entry(1), entry(2, { applied: true }), entry(3, { tags: ['clipped', 'acme'], title: 'Acme' })];
    const works = [{ id: 'w1', rel: 'imports:' + file(1) }, { id: 'w2', rel: 'imports:' + file(2) }, { id: 'wX', rel: file(3) }, { id: 'w4', rel: 'other/' + file(1) }];
    const p = pendingWork(clips, works);
    assert.deepEqual(p.map((x) => [x.file, x.id]), [[file(1), 'w1']]);
    assert.deepEqual(p[0].intents, [{ type: 'tags', id: 'w1', add: ['clipped'] }, { type: 'title', id: 'w1', title: 'Grab from alpha-site.test' }]);
    assert.deepEqual(pendingWork(clips, works.concat([{ id: 'w3', rel: 'imports:' + file(3) }])).map((x) => x.id), ['w1', 'w3']);
    assert.deepEqual(pendingWork(clips, null), []);
  });
});

describe('the manifest on disk', () => {
  it('a missing file is an empty manifest; write then read round-trips and leaves no temp file', () => {
    const dir = tmp();
    try {
      const f = path.join(dir, 'cosmos', MANIFEST_FILE);
      assert.deepEqual(readManifest(fs, f), { clips: [], status: 'missing' });
      writeManifest(fs, f, [entry(1), entry(2, { applied: true })]);
      const r = readManifest(fs, f);
      assert.equal(r.status, 'ok');
      assert.deepEqual(r.clips.map((c) => [c.file, c.applied]), [[file(1), false], [file(2), true]]);
      assert.deepEqual(fs.readdirSync(path.dirname(f)), [MANIFEST_FILE]);
    } finally { fs.rmSync(dir, { recursive: true, force: true }); }
  });
  it('a corrupt file is moved aside to .corrupt and never overwritten empty; a second one gets -2', () => {
    const dir = tmp();
    try {
      const f = path.join(dir, MANIFEST_FILE);
      fs.writeFileSync(f, '{ not json');
      let r = readManifest(fs, f);
      assert.deepEqual(r, { clips: [], status: 'quarantined' });
      assert.equal(fs.existsSync(f), false);
      assert.equal(fs.readFileSync(f + '.corrupt', 'utf8'), '{ not json');
      fs.writeFileSync(f, JSON.stringify({ v: 9, clips: [] }));   // valid JSON, wrong shape
      r = readManifest(fs, f);
      assert.equal(r.status, 'quarantined');
      assert.equal(fs.readFileSync(f + '.corrupt', 'utf8'), '{ not json', 'the first quarantine is never replaced');
      assert.ok(fs.existsSync(f + '.corrupt-2'));
    } finally { fs.rmSync(dir, { recursive: true, force: true }); }
  });
  it('a corrupt file that cannot be moved aside is "held": nothing is overwritten', () => {
    const dir = tmp();
    try {
      const f = path.join(dir, MANIFEST_FILE);
      fs.writeFileSync(f, 'garbage');
      const stuck = { ...fs, existsSync: fs.existsSync, renameSync: () => { throw new Error('locked'); } };
      assert.deepEqual(readManifest(stuck, f), { clips: [], status: 'held' });
      assert.equal(fs.readFileSync(f, 'utf8'), 'garbage');
    } finally { fs.rmSync(dir, { recursive: true, force: true }); }
  });
  it('an unreadable file (not just a missing one) is held, a BOM is tolerated', () => {
    const dir = tmp();
    try {
      const f = path.join(dir, MANIFEST_FILE);
      const eacces = { ...fs, readFileSync: () => { const e = new Error('no'); e.code = 'EACCES'; throw e; } };
      assert.equal(readManifest(eacces, f).status, 'held');
      fs.writeFileSync(f, '\ufeff' + JSON.stringify({ v: 1, clips: [entry(1)] }));
      assert.equal(readManifest(fs, f).clips.length, 1);
    } finally { fs.rmSync(dir, { recursive: true, force: true }); }
  });
  it('a failing rename leaves the old file intact and no temp file behind; the write is capped at 5000', () => {
    const dir = tmp();
    try {
      const f = path.join(dir, MANIFEST_FILE);
      writeManifest(fs, f, [entry(1)]);
      const broken = { ...fs, renameSync: () => { throw new Error('disk full'); } };
      assert.throws(() => writeManifest(broken, f, [entry(2)]), /disk full/);
      assert.deepEqual(readManifest(fs, f).clips.map((c) => c.file), [file(1)]);
      assert.deepEqual(fs.readdirSync(dir), [MANIFEST_FILE]);
      writeManifest(fs, f, Array.from({ length: MAX_CLIPS + 3 }, (_, i) => entry(i.toString(16))));
      assert.equal(readManifest(fs, f).clips.length, MAX_CLIPS);
    } finally { fs.rmSync(dir, { recursive: true, force: true }); }
  });
});
